# Fix the function name
def solve_between(grid, bg=3, fg=1):
    """3 becomes 2 if it has 1s on both left and right in input"""
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == fg:
                result[r][c] = fg
            elif val == bg:
                has_left_1 = (c > 0 and grid[r][c-1] == 1)
                has_right_1 = (c < cols - 1 and grid[r][c+1] == 1)
                if has_left_1 and has_right_1:
                    result[r][c] = 2
                else:
                    result[r][c] = bg
            else:
                result[r][c] = val
    return result

